import EarlGrey from "./teaBilder/EarlGrey.png"

export default function buttons(){
    const teaName = [
        {name :'Earl Greay', Image: EarlGrey}
    ];

    return(
        <div>
            {teaName.map((tea, index) => (
                <button key={index}>
                    {tea.name}
                    <img src={tea.Image[index]} />
                </button>
            ))}
        </div>
    );
}
